import type { BookSource, TextSourceId } from './editions.ts';
import type { Book, Chapter } from './usfm.ts';

/** Bump on any breaking change to the generated files in `data/bible/build/`. */
export const BIBLE_SCHEMA_VERSION = 1;

/** One book of one edition, as generated by `scripts/bible/build.ts`. */
export interface EditionBookFile {
  readonly schemaVersion: typeof BIBLE_SCHEMA_VERSION;
  readonly edition: string;
  readonly code: string;
  readonly source: TextSourceId;
  /** The book's name as printed in the source. */
  readonly sourceName: string;
  readonly note: { readonly en: string; readonly ar: string } | null;
  readonly chapters: readonly Chapter[];
}

/** Applies a `BookSource`'s chapter subset, renumbering and verse range to a parsed book. */
export function selectChapters(book: Book, source: BookSource): Chapter[] {
  let chapters = [...book.chapters];
  if (source.chapters !== undefined) {
    const wanted = source.chapters;
    chapters = wanted.map((number) => {
      const chapter = chapters.find((candidate) => candidate.number === number);
      if (chapter === undefined) throw new Error(`${source.source}/${source.book}: no chapter ${number}`);
      return chapter;
    });
  }
  if (source.verses !== undefined) {
    const [first, last] = source.verses;
    chapters = chapters.map((chapter) => ({
      ...chapter,
      verses: chapter.verses.filter((verse) => {
        const number = Number.parseInt(verse.number, 10);
        return number >= first && number <= last;
      }),
    }));
  }
  if (source.renumberFrom !== undefined) {
    const start = source.renumberFrom;
    chapters = chapters.map((chapter, index) => ({ ...chapter, number: start + index }));
  }
  if (chapters.length === 0 || chapters.some((chapter) => chapter.verses.length === 0)) {
    throw new Error(`${source.source}/${source.book}: selection produced an empty chapter`);
  }
  return chapters;
}
